  const onCompEnd=e=>{if(pending&&pick(e.target)){const hit=pending;pending=null;setTimeout(()=>send(hit),60)}};
  w.addEventListener('keydown',onKey,true);
  w.addEventListener('keypress',onPress,true);
  w.addEventListener('compositionend',onCompEnd,true);
  const ctl={off(){w.removeEventListener('keydown',onKey,true);w.removeEventListener('keypress',onPress,true);w.removeEventListener('compositionend',onCompEnd,true);if(w[ENTER_KEY]===ctl)delete w[ENTER_KEY]}};
