    const comp=d.querySelector('[data-sentry-component="ChatComposer"]')||d.querySelector('[data-sentry-component="ChatInput"]');
    if(!comp)return;
    const list=d.querySelector('[data-sentry-component="ChatMessageList"]');
    let root=comp;
    while(root.parentElement&&root.parentElement!==d.body&&!(list&&root.parentElement.contains(list)))root=root.parentElement;
    const zones=[root];
    const room=root.parentElement;
    if(room&&room!==d.body)[...room.children].forEach(ch=>{if(ch!==root&&!(list&&ch.contains(list))){const r=ch.getBoundingClientRect(),cr=comp.getBoundingClientRect();if(r.bottom>=cr.top-80&&r.height<w.innerHeight*0.5)zones.push(ch)}});
    zones.forEach(z=>{mark(z);z.querySelectorAll('*').forEach(mark)});
    for(let el=comp;el&&el!==root;el=el.parentElement)mark(el);
